refentry.refsect1:
&reftitle.description;
public mixedReflectionFunction::invokeArgs arrayargs
Метод вызывает функцию с передачей массива аргументов.

&reftitle.changelog;







     &Version;
     &Description;





     8.0.0

      Ключи args теперь интерпретируются как названия параметров, а не игнорируются молча.

  &reftitle.examples;



    Пример вызова функции методом ReflectionFunction::invokeArgs


<?php

function title($title, $name)
{
    return sprintf("%s. %s\r\n", $title, $name);
}

$function = new ReflectionFunction('title');

echo $function->invokeArgs(array('Dr', 'Phil'));


    &example.outputs;


Dr. Phil








     Пример вызова метода
     ReflectionFunction::invokeArgs со ссылками
     на аргументы



<?php

function get_false_conditions(array $conditions, array &$false_conditions)
{
    foreach ($conditions as $condition) {
        if (!$condition) {
            $false_conditions[] = $condition;
        }
    }
}

$function_ref     = new ReflectionFunction('get_false_conditions');

$conditions       = array(true, false, -1, 0, 1);
$false_conditions = array();

$function_ref->invokeArgs(array($conditions, &$false_conditions));

var_dump($false_conditions);


    &example.outputs;


array(2) {
  [0]=>
  bool(false)
  [1]=>
  int(0)
}
